template<class T>
class list {
    void *node;
};

class game_process;
class nglTexture;
class camera;
class TimeAttackMode;
class MeterAttackMode;
class HeadToHeadMode;

class PushMode {
};

struct PlayMode {
    TimeAttackMode *timeAttack;
    MeterAttackMode *meterAttack;
    HeadToHeadMode *headToHead;
    PushMode *push;
};

struct game_recti {
    int x0;
    int y0;
    int x1;
    int y1;
};

class game {
    char data_before_process_stack[0x5c];
    list<game_process> process_stack;
    char data_after_process_stack[0x08];
    int snapshotState;
    nglTexture *destSnapshot;
    int renderState;
    int game_mode;
    PlayMode play_mode;
    camera *player_cam[2];
    game_recti player_viewports[2];
    int num_players;
    int num_ai_players;
    int num_active_players;
    int active_player;

public:
    inline int get_game_mode() const { return game_mode; }
    inline int get_beach_id() const {
        return *(const int *)((const char *)this + 0x228);
    }
};

enum {
    GAME_MODE_FREESURF_ICON = 3,
    NUM_ROWS = 10
};

struct HighScoreData {
    char initials[4];
    char character[32];
    int score;
    int icons;
};

class GlobalDataClass {
public:
    HighScoreData getBeachHighScore(
        int beach,
        int whichScore,
        bool icons);
};

enum CheatId {
    CHEAT_RAINBOW,
    CHEAT_TRIPPY,
    CHEAT_FREAK_BOY,
    CHEAT_TONY_HAWK,
    CHEAT_TIKI_GOD,
    CHEAT_TRAVIS_PASTRANA,
    CHEAT_FPS_CAM,
    CHEAT_INCREASE_BALANCE,
    CHEAT_SUPER_BALANCE,
    CHEAT_INCREASE_JUMP,
    CHEAT_SUPER_JUMP,
    CHEAT_PERFECT_BALANCE,
    CHEAT_CAREER_PERSONALITY_SUIT,
    CHEAT_ALL_PERSONALITY_SUITS,
    CHEAT_BAILS_MOVIE,
    CHEAT_ESPN_MOVIE,
    CHEAT_ALL_LEVELS,
    CHEAT_ALL_BOARDS,
    CHEAT_UNLOCK_ALL_SURFERS,
    CHEAT_UNLOCK_ALL_SURFER_TRICKS,
    CHEAT_UNLOCK_ALL_SKILL_POINTS,
    CHEAT_MEGA_CHEAT,
    CHEAT_LAST
};

class Cheat {
    bool locked;
    bool on;

public:
    bool isOn() const { return on; }
};

class HighScoreFrontEnd {
public:
    static bool IsNewHighScore(int score, int icons);
};

extern game *g_game_ptr;
extern GlobalDataClass globalCareerData;
extern Cheat g_session_cheats[CHEAT_LAST];

__asm__(".equ g_game_ptr, 0x0046AC64");
__asm__(".equ globalCareerData, 0x004349B8");
__asm__(".equ getBeachHighScore__15GlobalDataClassiib, 0x002F0020");
__asm__(".equ g_session_cheats, 0x0043BD48");

bool HighScoreFrontEnd::IsNewHighScore(const int score, const int icons)
{
	bool icon_mode = g_game_ptr->get_game_mode() == GAME_MODE_FREESURF_ICON;
	int lowest_high = globalCareerData.getBeachHighScore(g_game_ptr->get_beach_id(), NUM_ROWS-1, icon_mode).score;
	int lowest_high_i = globalCareerData.getBeachHighScore(g_game_ptr->get_beach_id(), NUM_ROWS-1, icon_mode).icons;

	for(int i=0; i<CHEAT_LAST; i++)
	{
		if (g_session_cheats[i].isOn())
			return false;
	}
	if ((!icon_mode && score > lowest_high || (icon_mode && icons > lowest_high_i)))
		return true;

	return false;
}
